const input = $json || {};
const payload = (input.body && typeof input.body === 'object') ? input.body : input;
const startedAtISO = new Date().toISOString();
const dryRun = payload.dryRun === true;

if (payload.days === undefined || payload.days === null || payload.days === '') {
  return [{ json: { ok: true, days: 30, dryRun, startedAtISO } }];
}

const d = Number(payload.days);
if (!Number.isFinite(d) || Math.trunc(d) < 1) {
  return [{
    json: {
      ok: false,
      reason: 'INVALID_DAYS',
      message: 'days must be a positive integer',
      dryRun,
      startedAtISO
    }
  }];
}

return [{ json: { ok: true, days: Math.min(90, Math.trunc(d)), dryRun, startedAtISO } }];

const req = $('Parse_Request').first().json || {};
const days = Number(req.days || 30);
const startedAtISO = req.startedAtISO || new Date().toISOString();
const rows = $input.all().map((i) => i.json || {});

if (!rows.length) {
  return [{
    json: {
      ok: false,
      reason: 'NO_RAW_DATA',
      message: 'raw_events is empty',
      days,
      startedAtISO,
      summary: {
        rawRowsRead: 0,
        windowRows: 0,
        uniqueVideos: 0,
        dailyRows: 0,
        keywordRows: 0,
        snippetRows: 0,
        rejectedCount: 0
      }
    }
  }];
}

const toNumOrNull = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const toDateString = (v) => {
  if (typeof v === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(v)) return v;
  return null;
};

const toIso = (v) => {
  if (!v) return null;
  const d = new Date(v);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
};

const now = new Date();
const todayKST = now.toLocaleDateString('en-CA', { timeZone: 'Asia/Seoul' });
const start = new Date(now.getTime() - (Math.max(1, days) - 1) * 86400000);
const startKST = start.toLocaleDateString('en-CA', { timeZone: 'Asia/Seoul' });

const normalized = rows.map((r) => {
  const collectedAtISO = toIso(r.collectedAtISO);
  const createTimeISO = toIso(r.createTimeISO);
  const createDateKST = toDateString(r.createDateKST);

  return {
    collectedAtISO,
    collectedDateKST: toDateString(r.collectedDateKST),
    createTimeISO,
    createDateKST,
    bucket: r.bucket || null,
    keyword: r.keyword || null,
    query: r.query || null,
    proxyCountryCode: r.proxyCountryCode || null,
    id: r.id || null,
    text: r.text || null,
    textLanguage: r.textLanguage || null,
    videoUrl: r.videoUrl || null,
    authorName: r.authorName || null,
    authorNickName: r.authorNickName || null,
    authorProfileUrl: r.authorProfileUrl || null,
    authorFollowers: toNumOrNull(r.authorFollowers),
    playCount: toNumOrNull(r.playCount),
    diggCount: toNumOrNull(r.diggCount),
    shareCount: toNumOrNull(r.shareCount),
    commentCount: toNumOrNull(r.commentCount),
    inLookback: r.inLookback === true || r.inLookback === 'TRUE' || r.inLookback === 'true'
  };
});

const filtered = normalized.filter((r) => r.id && r.createDateKST && r.createDateKST >= startKST && r.createDateKST <= todayKST);

const dedupe = new Map();
for (const row of filtered) {
  const prev = dedupe.get(row.id);
  if (!prev) {
    dedupe.set(row.id, row);
    continue;
  }
  const prevTs = new Date(prev.collectedAtISO || 0).getTime();
  const currTs = new Date(row.collectedAtISO || 0).getTime();
  if (currTs >= prevTs) dedupe.set(row.id, row);
}

const dedupedRows = Array.from(dedupe.values());
const warning = dedupedRows.length === 0 ? 'NO_ROWS_AFTER_DEDUPE' : null;

return [{
  json: {
    ok: dedupedRows.length > 0,
    reason: dedupedRows.length > 0 ? null : 'NO_DEDUPED_ROWS',
    warning,
    days,
    startedAtISO,
    windowStartKST: startKST,
    windowEndKST: todayKST,
    totalRawRows: rows.length,
    filteredRows: filtered.length,
    dedupedRows,
    summary: {
      rawRowsRead: rows.length,
      windowRows: filtered.length,
      uniqueVideos: dedupedRows.length,
      dailyRows: 0,
      keywordRows: 0,
      snippetRows: 0,
      rejectedCount: Math.max(0, rows.length - filtered.length)
    }
  }
}];

const payload = $json || {};
const rows = Array.isArray(payload.dedupedRows) ? payload.dedupedRows : [];
const topN = Math.max(1, Number($env.TOP_SNIPPETS_N || 5));

const numStat = () => ({ sum: 0, count: 0 });
const addNum = (stat, val) => {
  if (val === null || val === undefined || val === '') return;
  const n = Number(val);
  if (!Number.isFinite(n)) return;
  stat.sum += n;
  stat.count += 1;
};
const statValue = (stat) => (stat.count > 0 ? stat.sum : null);
const statAvg = (stat, baseCount) => (baseCount > 0 && stat.count > 0 ? +(stat.sum / baseCount).toFixed(2) : null);

const byDaily = new Map();
for (const r of rows) {
  const key = `${r.createDateKST}||${r.bucket || ''}||${r.keyword || ''}`;
  if (!byDaily.has(key)) {
    byDaily.set(key, {
      date_kst: r.createDateKST,
      bucket: r.bucket || null,
      keyword: r.keyword || null,
      videos_count: 0,
      play: numStat(), digg: numStat(), share: numStat(), comment: numStat()
    });
  }
  const cur = byDaily.get(key);
  cur.videos_count += 1;
  addNum(cur.play, r.playCount);
  addNum(cur.digg, r.diggCount);
  addNum(cur.share, r.shareCount);
  addNum(cur.comment, r.commentCount);
}

const dailyRows = Array.from(byDaily.values())
  .map((r) => ({
    date_kst: r.date_kst,
    bucket: r.bucket,
    keyword: r.keyword,
    videos_count: r.videos_count,
    play_sum: statValue(r.play),
    digg_sum: statValue(r.digg),
    share_sum: statValue(r.share),
    comment_sum: statValue(r.comment),
    play_avg: statAvg(r.play, r.videos_count),
    digg_avg: statAvg(r.digg, r.videos_count),
    share_avg: statAvg(r.share, r.videos_count),
    comment_avg: statAvg(r.comment, r.videos_count)
  }))
  .sort((a, b) => a.date_kst.localeCompare(b.date_kst) || (a.bucket || '').localeCompare(b.bucket || '') || (a.keyword || '').localeCompare(b.keyword || ''));

const byKeyword = new Map();
for (const r of rows) {
  const key = `${r.bucket || ''}||${r.keyword || ''}`;
  if (!byKeyword.has(key)) {
    byKeyword.set(key, {
      bucket: r.bucket || null,
      keyword: r.keyword || null,
      videos_count: 0,
      play: numStat(), digg: numStat(), share: numStat(), comment: numStat()
    });
  }
  const cur = byKeyword.get(key);
  cur.videos_count += 1;
  addNum(cur.play, r.playCount);
  addNum(cur.digg, r.diggCount);
  addNum(cur.share, r.shareCount);
  addNum(cur.comment, r.commentCount);
}

const keywordRows = Array.from(byKeyword.values())
  .map((r) => ({
    bucket: r.bucket,
    keyword: r.keyword,
    videos_count: r.videos_count,
    play_sum: statValue(r.play),
    digg_sum: statValue(r.digg),
    share_sum: statValue(r.share),
    comment_sum: statValue(r.comment),
    play_per_video: statAvg(r.play, r.videos_count),
    digg_per_video: statAvg(r.digg, r.videos_count),
    share_per_video: statAvg(r.share, r.videos_count),
    comment_per_video: statAvg(r.comment, r.videos_count)
  }))
  .sort((a, b) => (a.bucket || '').localeCompare(b.bucket || '') || (a.keyword || '').localeCompare(b.keyword || ''));

const byBucketKeyword = new Map();
for (const r of rows) {
  const key = `${r.bucket || ''}||${r.keyword || ''}`;
  if (!byBucketKeyword.has(key)) byBucketKeyword.set(key, []);
  byBucketKeyword.get(key).push(r);
}

const snippetRows = [];
for (const arr of byBucketKeyword.values()) {
  const sorted = [...arr].sort((a, b) => {
    const ap = Number.isFinite(Number(a.playCount)) ? Number(a.playCount) : -1;
    const bp = Number.isFinite(Number(b.playCount)) ? Number(b.playCount) : -1;
    return bp - ap;
  }).slice(0, topN);

  for (const r of sorted) {
    snippetRows.push({
      bucket: r.bucket,
      keyword: r.keyword,
      id: r.id,
      createDateKST: r.createDateKST,
      createTimeISO: r.createTimeISO,
      playCount: r.playCount,
      diggCount: r.diggCount,
      shareCount: r.shareCount,
      commentCount: r.commentCount,
      text: r.text,
      videoUrl: r.videoUrl,
      authorNickName: r.authorNickName,
      authorFollowers: r.authorFollowers
    });
  }
}

const dailyHeader = ['date_kst','bucket','keyword','videos_count','play_sum','digg_sum','share_sum','comment_sum','play_avg','digg_avg','share_avg','comment_avg'];
const keywordHeader = ['bucket','keyword','videos_count','play_sum','digg_sum','share_sum','comment_sum','play_per_video','digg_per_video','share_per_video','comment_per_video'];
const snippetHeader = ['bucket','keyword','id','createDateKST','createTimeISO','playCount','diggCount','shareCount','commentCount','text','videoUrl','authorNickName','authorFollowers'];

const summary = {
  rawRowsRead: Number(payload.totalRawRows || 0),
  windowRows: Number(payload.filteredRows || 0),
  uniqueVideos: rows.length,
  dailyRows: dailyRows.length,
  keywordRows: keywordRows.length,
  snippetRows: snippetRows.length,
  rejectedCount: Math.max(0, Number(payload.totalRawRows || 0) - Number(payload.filteredRows || 0))
};

return [{
  json: {
    ok: true,
    days: payload.days,
    startedAtISO: payload.startedAtISO || new Date().toISOString(),
    windowStartKST: payload.windowStartKST,
    windowEndKST: payload.windowEndKST,
    totalRawRows: payload.totalRawRows,
    filteredRows: payload.filteredRows,
    dedupedRows: rows.length,
    warning: payload.warning || null,
    summary,
    sampleDedupedTop1: rows[0] ?? null,
    top5MappedRows: rows.slice(0, 5),
    dailyPreviewTop3: dailyRows.slice(0, 3),
    keywordPreviewTop3: keywordRows.slice(0, 3),
    snippetsPreviewTop3: snippetRows.slice(0, 3),
    dailyMatrix: [dailyHeader, ...dailyRows.map((r) => dailyHeader.map((h) => r[h] ?? null))],
    keywordMatrix: [keywordHeader, ...keywordRows.map((r) => keywordHeader.map((h) => r[h] ?? null))],
    snippetMatrix: [snippetHeader, ...snippetRows.map((r) => snippetHeader.map((h) => r[h] ?? null))]
  }
}];

const fallback = $json || {};
let built = null;
try {
  built = $('Build_Aggregates').first().json;
} catch {
  built = null;
}

const source = built || fallback;
const startedAtISO = source.startedAtISO || new Date().toISOString();
const finishedAtISO = new Date().toISOString();
const durationMs = Math.max(0, new Date(finishedAtISO).getTime() - new Date(startedAtISO).getTime());

const defaultWouldWriteRanges = {
  clearDaily: `${$env.GSHEET_DAILY_TAB || 'daily_metrics'}!A1:Z`,
  writeDaily: `${$env.GSHEET_DAILY_TAB || 'daily_metrics'}!A1:Z`,
  clearKeyword: `${$env.GSHEET_KEYWORD_TAB || 'keyword_totals'}!A1:Z`,
  writeKeyword: `${$env.GSHEET_KEYWORD_TAB || 'keyword_totals'}!A1:Z`,
  clearSnippets: `${$env.GSHEET_SNIPPETS_TAB || 'top_snippets'}!A1:Z`,
  writeSnippets: `${$env.GSHEET_SNIPPETS_TAB || 'top_snippets'}!A1:Z`
};

if (source.ok === false) {
  return [{
    json: {
      ok: false,
      dryRun: source.dryRun === true,
      reason: source.reason || 'AGGREGATION_ABORTED',
      message: source.message || null,
      warning: source.warning || null,
      startedAt: startedAtISO,
      finishedAt: finishedAtISO,
      durationMs,
      wouldWriteRanges: source.wouldWriteRanges || defaultWouldWriteRanges,
      summary: source.summary || {
        rawRowsRead: 0,
        windowRows: 0,
        uniqueVideos: 0,
        dailyRows: 0,
        keywordRows: 0,
        snippetRows: 0,
        rejectedCount: 0
      },
      dailyPreviewTop3: [],
      keywordPreviewTop3: [],
      snippetsPreviewTop3: []
    }
  }];
}

return [{
  json: {
    ok: true,
    dryRun: source.dryRun === true,
    workflow: 'KoreaSignals_Aggregator',
    days: source.days,
    windowStartKST: source.windowStartKST,
    windowEndKST: source.windowEndKST,
    startedAt: startedAtISO,
    finishedAt: finishedAtISO,
    durationMs,
    warning: source.warning || null,
    wouldWriteRanges: source.wouldWriteRanges || defaultWouldWriteRanges,
    summary: source.summary || {
      rawRowsRead: Number(source.totalRawRows || 0),
      windowRows: Number(source.filteredRows || 0),
      uniqueVideos: Number(source.dedupedRows || 0),
      dailyRows: 0,
      keywordRows: 0,
      snippetRows: 0,
      rejectedCount: Math.max(0, Number(source.totalRawRows || 0) - Number(source.filteredRows || 0))
    },
    sampleDedupedTop1: source.sampleDedupedTop1 || null,
    top5MappedRows: source.top5MappedRows || [],
    dailyPreviewTop3: source.dailyPreviewTop3 || [],
    keywordPreviewTop3: source.keywordPreviewTop3 || [],
    snippetsPreviewTop3: source.snippetsPreviewTop3 || []
  }
}];

const req = $('Parse_Request').first().json || {};
const count = $input.all().length;
const rawRowsRead = Math.max(0, count - 1);

return [{
  json: {
    ok: true,
    dryRun: true,
    reason: 'DRY_RUN',
    message: 'No write operations were executed',
    startedAtISO: req.startedAtISO || new Date().toISOString(),
    days: req.days || 30,
    summary: {
      rawRowsRead,
      windowRows: null,
      uniqueVideos: null,
      dailyRows: null,
      keywordRows: null,
      snippetRows: null,
      rejectedCount: null
    },
    wouldWriteRanges: {
      clearDaily: `${$env.GSHEET_DAILY_TAB || 'daily_metrics'}!A1:Z`,
      writeDaily: `${$env.GSHEET_DAILY_TAB || 'daily_metrics'}!A1:Z`,
      clearKeyword: `${$env.GSHEET_KEYWORD_TAB || 'keyword_totals'}!A1:Z`,
      writeKeyword: `${$env.GSHEET_KEYWORD_TAB || 'keyword_totals'}!A1:Z`,
      clearSnippets: `${$env.GSHEET_SNIPPETS_TAB || 'top_snippets'}!A1:Z`,
      writeSnippets: `${$env.GSHEET_SNIPPETS_TAB || 'top_snippets'}!A1:Z`
    }
  }
}];

const input = $json || {};
const payload = (input.body && typeof input.body === 'object') ? input.body : input;

const fallback = { keywords: ['Gen Z travel', '혼자여행'], days: 30, dryRun: false };
const source = (Array.isArray(payload.keywords) || payload.days !== undefined || payload.dryRun !== undefined) ? payload : fallback;

const keywords = (Array.isArray(source.keywords) ? source.keywords : [])
  .map((k) => (typeof k === 'string' ? k.trim() : ''))
  .filter((k) => k.length > 0)
  .slice(0, 30);

if (!keywords.length) {
  return [{
    json: {
      ok: false,
      reason: 'INVALID_KEYWORDS',
      message: 'keywords must be a non-empty array of strings',
      startedAtISO: new Date().toISOString()
    }
  }];
}

const d = Number(source.days);
if (!Number.isFinite(d) || Math.trunc(d) < 1) {
  return [{
    json: {
      ok: false,
      reason: 'INVALID_DAYS',
      message: 'days must be a positive integer',
      startedAtISO: new Date().toISOString(),
      keywords,
      dryRun: Boolean(source.dryRun)
    }
  }];
}

const dryRun = source.dryRun === true;
const days = Math.min(90, Math.trunc(d));

return [{
  json: {
    ok: true,
    keywords,
    days,
    dryRun,
    startedAtISO: new Date().toISOString()
  }
}];

const req = $('Parse_Request').first().json || {};

if (req.ok === false) {
  return [{
    json: {
      skipWorkflow: true,
      dryRun: Boolean(req.dryRun),
      startedAtISO: req.startedAtISO || new Date().toISOString(),
      fatalErrorCode: req.reason || 'INVALID_REQUEST',
      fatalErrorMessage: req.message || 'Invalid request payload',
      jobsTotal: 0,
      jobsSucceeded: 0,
      jobsFailed: 1,
      sheetsRangesWouldWrite: {
        ensureHeader: `${$env.GSHEET_RAW_TAB || 'raw_events'}!A1:U1`,
        appendRows: `${$env.GSHEET_RAW_TAB || 'raw_events'}!A:U`
      }
    }
  }];
}

const { keywords, days, startedAtISO, dryRun } = req;
const actorRaw = String($env.APIFY_ACTOR || '').trim();
const token = String($env.APIFY_TOKEN || '').trim();

const buckets = [
  { bucket: 'GLOBAL', proxyCountryCode: 'US' },
  { bucket: 'KR', proxyCountryCode: 'KR' }
];

const jobsCount = buckets.length * keywords.length;
const maxItemsPerRun = Math.max(1, Number.parseInt($env.MAX_ITEMS_PER_RUN || '2000', 10) || 2000);
const requestedPerJob = Math.max(1, Number.parseInt($env.APIFY_RESULTS_PER_PAGE || '20', 10) || 20);
const perJobCap = Math.max(1, Math.floor(maxItemsPerRun / Math.max(1, jobsCount)));
const resultsLimit = Math.max(1, Math.min(200, requestedPerJob, perJobCap));

const actorNormalized = (actorRaw || 'clockworks/tiktok-scraper').replace(/\//g, '~');
const waitForFinish = Number.parseInt($env.APIFY_WAIT_FOR_FINISH_SECS || '180', 10) || 180;

const missing = [];
if (!dryRun && !actorRaw) missing.push('APIFY_ACTOR');
if (!dryRun && !token) missing.push('APIFY_TOKEN');

if (missing.length > 0) {
  return [{
    json: {
      skipWorkflow: true,
      dryRun,
      startedAtISO: startedAtISO || new Date().toISOString(),
      fatalErrorCode: 'MISSING_ENV',
      fatalErrorMessage: `Missing required environment variable(s): ${missing.join(', ')}`,
      missingEnvVars: missing,
      jobsTotal: jobsCount,
      jobsSucceeded: 0,
      jobsFailed: jobsCount,
      perJobCap,
      resultsLimit,
      sheetsRangesWouldWrite: {
        ensureHeader: `${$env.GSHEET_RAW_TAB || 'raw_events'}!A1:U1`,
        appendRows: `${$env.GSHEET_RAW_TAB || 'raw_events'}!A:U`
      }
    }
  }];
}

const jobs = [];
for (const b of buckets) {
  for (const keyword of keywords) {
    const query = keyword;
    const runUrlNoToken = `https://api.apify.com/v2/acts/${actorNormalized}/runs?waitForFinish=${waitForFinish}`;
    const runUrl = `${runUrlNoToken}&token=${token || '<APIFY_TOKEN>'}`;
    const datasetUrlTemplate = `https://api.apify.com/v2/datasets/{datasetId}/items?clean=true&format=json&limit=${resultsLimit}&token=${token || '<APIFY_TOKEN>'}`;

    jobs.push({
      days,
      dryRun,
      bucket: b.bucket,
      proxyCountryCode: b.proxyCountryCode,
      keyword,
      query,
      actorRaw,
      actorNormalized,
      startedAtISO: startedAtISO || new Date().toISOString(),
      jobStartedAtISO: new Date().toISOString(),
      skipWorkflow: false,
      jobsCount,
      perJobCap,
      resultsLimit,
      apifyRunUrl: runUrl,
      apifyRunUrlNoToken: runUrlNoToken,
      apifyDatasetItemsUrlTemplate: datasetUrlTemplate,
      sheetsRangesWouldWrite: {
        ensureHeader: `${$env.GSHEET_RAW_TAB || 'raw_events'}!A1:U1`,
        appendRows: `${$env.GSHEET_RAW_TAB || 'raw_events'}!A:U`
      }
    });
  }
}

return jobs.map((j) => ({ json: j }));

const job = $('Split_Jobs').item.json || {};

const errorOut = (stage, code, httpStatus, message, retriable) => {
  return [{
    json: {
      ...job,
      ok: false,
      stage,
      error: { code, httpStatus, message, retriable },
      rawItems: [],
      datasetId: null,
      fetchedAtISO: new Date().toISOString()
    }
  }];
};

const token = String($env.APIFY_TOKEN || '').trim();
const actorId = String(job.actorNormalized || '').trim();
if (!token) return errorOut('Run_Apify_TikTok', 'MISSING_APIFY_TOKEN', 400, 'APIFY_TOKEN is not configured', false);
if (!actorId) return errorOut('Run_Apify_TikTok', 'MISSING_APIFY_ACTOR', 400, 'APIFY_ACTOR is not configured', false);

const waitForFinish = Number.parseInt($env.APIFY_WAIT_FOR_FINISH_SECS || '180', 10) || 180;
const runUrl = `https://api.apify.com/v2/acts/${actorId}/runs?waitForFinish=${waitForFinish}&token=${token}`;

const runInput = {
  searchQueries: [job.query],
  proxyCountryCode: job.proxyCountryCode,
  resultsPerPage: Number(job.resultsLimit || 20),
  searchSection: '/video'
};

const parseJsonSafe = async (res) => {
  try {
    return await res.json();
  } catch {
    return null;
  }
};

const retriableByStatus = (status) => [429, 500, 502, 503, 504].includes(status);

let runRes;
try {
  runRes = await fetch(runUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(runInput)
  });
} catch (err) {
  return errorOut('Run_Apify_TikTok', 'APIFY_RUN_NETWORK_ERROR', null, String(err.message || err), true);
}

const runBody = await parseJsonSafe(runRes);
if (!runRes.ok) {
  const msg = runBody?.error?.message || runBody?.message || `Apify run call failed (${runRes.status})`;
  return errorOut('Run_Apify_TikTok', 'APIFY_RUN_FAILED', runRes.status, msg, retriableByStatus(runRes.status));
}

let datasetId = runBody?.data?.defaultDatasetId || runBody?.data?.datasetId || runBody?.defaultDatasetId || runBody?.datasetId || null;
const runId = runBody?.data?.id || runBody?.id || null;

if (!datasetId && runId) {
  const runInfoUrl = `https://api.apify.com/v2/actor-runs/${runId}?token=${token}`;
  try {
    const infoRes = await fetch(runInfoUrl, { method: 'GET' });
    const infoBody = await parseJsonSafe(infoRes);
    if (infoRes.ok) {
      datasetId = infoBody?.data?.defaultDatasetId || infoBody?.data?.datasetId || infoBody?.defaultDatasetId || infoBody?.datasetId || null;
    }
  } catch {
    // keep fallback error below
  }
}

if (!datasetId) {
  return errorOut('Run_Apify_TikTok', 'MISSING_DATASET_ID', 502, 'Apify run succeeded but datasetId was not found in run result or run info endpoint', false);
}

const limit = Number(job.resultsLimit || 20);
const datasetItemsUrl = `https://api.apify.com/v2/datasets/${datasetId}/items?clean=true&format=json&limit=${limit}&token=${token}`;

const maxRetries = 5;
let attempt = 0;
let itemsRes = null;
let itemsBody = null;

while (attempt < maxRetries) {
  attempt += 1;
  try {
    itemsRes = await fetch(datasetItemsUrl, { method: 'GET' });
    itemsBody = await parseJsonSafe(itemsRes);

    if (itemsRes.status !== 429) break;

    if (attempt >= maxRetries) {
      return errorOut('Fetch_Dataset_Items', 'APIFY_DATASET_RATE_LIMIT', itemsRes.status, 'Dataset items endpoint rate-limited after retries', true);
    }

    const backoffMs = 1000 * (2 ** (attempt - 1));
    await new Promise((resolve) => setTimeout(resolve, backoffMs));
  } catch (err) {
    if (attempt >= maxRetries) {
      return errorOut('Fetch_Dataset_Items', 'APIFY_DATASET_NETWORK_ERROR', null, String(err.message || err), true);
    }
    const backoffMs = 1000 * (2 ** (attempt - 1));
    await new Promise((resolve) => setTimeout(resolve, backoffMs));
  }
}

if (!itemsRes || !itemsRes.ok) {
  const status = itemsRes?.status ?? null;
  const msg = itemsBody?.error?.message || itemsBody?.message || `Dataset items fetch failed (${status ?? 'no status'})`;
  return errorOut('Fetch_Dataset_Items', 'APIFY_DATASET_FETCH_FAILED', status, msg, retriableByStatus(status || 0));
}

const rawItems = Array.isArray(itemsBody)
  ? itemsBody
  : Array.isArray(itemsBody?.data)
    ? itemsBody.data
    : [];

return [{
  json: {
    ...job,
    ok: true,
    stage: 'Fetch_Dataset_Items',
    error: null,
    datasetId,
    apifyRunId: runId,
    datasetItemsUrl,
    rawItems,
    sampleRawItemTop1: rawItems.length ? rawItems[0] : null,
    fetchedAtISO: new Date().toISOString()
  }
}];

const started = Date.now();
try {
  const payload = $json || {};
  const job = $('Split_Jobs').item.json || {};

  if (job.dryRun === true) {
    const nowIso = new Date().toISOString();
    return [{
      json: {
        ...job,
        ok: true,
        dryRun: true,
        fetchedCount: 0,
        inLookbackCount: 0,
        appendCountPlanned: 0,
        rowsMatrix: [],
        sampleRawItemTop1: null,
        top5MappedRows: { columns: [], rows: [] },
        startedAtISO: job.jobStartedAtISO || job.startedAtISO || nowIso,
        finishedAtISO: nowIso,
        durationMs: Math.max(0, Date.now() - new Date(job.jobStartedAtISO || job.startedAtISO || nowIso).getTime()),
        errorMessage: null
      }
    }];
  }

  if (payload.ok === false || payload.error) {
    const nowIso = new Date().toISOString();
    return [{
      json: {
        ...job,
        ok: false,
        stage: payload.stage || 'Run_Apify_TikTok',
        error: payload.error || null,
        fetchedCount: 0,
        inLookbackCount: 0,
        appendCountPlanned: 0,
        rowsMatrix: [],
        sampleRawItemTop1: null,
        top5MappedRows: { columns: [], rows: [] },
        startedAtISO: job.jobStartedAtISO || job.startedAtISO || nowIso,
        finishedAtISO: nowIso,
        durationMs: Math.max(0, Date.now() - new Date(job.jobStartedAtISO || job.startedAtISO || nowIso).getTime()),
        errorMessage: payload.error?.message || 'Apify execution failed'
      }
    }];
  }

  const rawItems = Array.isArray(payload.rawItems) ? payload.rawItems : [];

  const toNumOrNull = (v) => {
    if (v === null || v === undefined || v === '') return null;
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
  };

  const toIso = (v) => {
    if (v === null || v === undefined || v === '') return null;
    if (typeof v === 'number') {
      const ms = v > 1e12 ? v : v > 1e9 ? v * 1000 : null;
      if (!ms) return null;
      const d = new Date(ms);
      return Number.isNaN(d.getTime()) ? null : d.toISOString();
    }
    const d = new Date(v);
    return Number.isNaN(d.getTime()) ? null : d.toISOString();
  };

  const toKstDate = (iso) => {
    if (!iso) return null;
    const d = new Date(iso);
    if (Number.isNaN(d.getTime())) return null;
    return d.toLocaleDateString('en-CA', { timeZone: 'Asia/Seoul' });
  };

  const nowIso = new Date().toISOString();
  const todayKst = toKstDate(nowIso);
  const startDate = new Date(Date.now() - (Math.max(1, Number(job.days || 30)) - 1) * 86400000);
  const startKst = startDate.toLocaleDateString('en-CA', { timeZone: 'Asia/Seoul' });

  const mappedRows = rawItems.map((item) => {
    const createTimeISO = toIso(item.createTimeISO ?? item.createTime ?? item.createdAt ?? null);
    const createDateKST = toKstDate(createTimeISO);
    const inLookback = Boolean(createDateKST && createDateKST >= startKst && createDateKST <= todayKst);
    const author = item.authorMeta || {};

    return {
      collectedAtISO: nowIso,
      collectedDateKST: todayKst,
      createTimeISO,
      createDateKST,
      bucket: job.bucket,
      keyword: job.keyword,
      query: job.query,
      proxyCountryCode: job.proxyCountryCode,
      id: item.id ?? null,
      text: item.text ?? null,
      textLanguage: item.textLanguage ?? null,
      videoUrl: item.webVideoUrl ?? item.videoUrl ?? null,
      authorName: author.name ?? null,
      authorNickName: author.nickName ?? null,
      authorProfileUrl: author.profileUrl ?? null,
      authorFollowers: toNumOrNull(author.fans),
      playCount: toNumOrNull(item.playCount),
      diggCount: toNumOrNull(item.diggCount),
      shareCount: toNumOrNull(item.shareCount),
      commentCount: toNumOrNull(item.commentCount),
      inLookback
    };
  });

  const rowsMatrix = mappedRows.map((r) => ([
    r.collectedAtISO,
    r.collectedDateKST,
    r.createTimeISO,
    r.createDateKST,
    r.bucket,
    r.keyword,
    r.query,
    r.proxyCountryCode,
    r.id,
    r.text,
    r.textLanguage,
    r.videoUrl,
    r.authorName,
    r.authorNickName,
    r.authorProfileUrl,
    r.authorFollowers,
    r.playCount,
    r.diggCount,
    r.shareCount,
    r.commentCount,
    r.inLookback
  ]));

  const previewColumns = [
    'collectedAtISO','collectedDateKST','createTimeISO','createDateKST','bucket','keyword','query','proxyCountryCode','id','text','textLanguage','videoUrl','authorName','authorNickName','authorProfileUrl','authorFollowers','playCount','diggCount','shareCount','commentCount','inLookback'
  ];

  const finishedAtISO = new Date().toISOString();
  const durationMs = Date.now() - (new Date(job.jobStartedAtISO || job.startedAtISO || finishedAtISO).getTime() || Date.now());

  return [{
    json: {
      ...job,
      ok: true,
      actorUsed: job.actorNormalized,
      requestedDays: Number(job.days || 30),
      fetchedCount: mappedRows.length,
      inLookbackCount: mappedRows.filter((r) => r.inLookback).length,
      appendCountPlanned: mappedRows.length,
      rowsMatrix,
      datasetId: payload.datasetId || null,
      apifyRunId: payload.apifyRunId || null,
      apifyRunUrl: job.apifyRunUrl,
      apifyDatasetItemsUrl: payload.datasetItemsUrl || null,
      sampleRawItemTop1: rawItems.length > 0 ? rawItems[0] : null,
      top5MappedRows: {
        columns: previewColumns,
        rows: mappedRows.slice(0, 5)
      },
      startedAtISO: job.jobStartedAtISO || job.startedAtISO || nowIso,
      finishedAtISO,
      durationMs,
      errorMessage: null
    }
  }];
} catch (err) {
  return [{
    json: {
      ok: false,
      fetchedCount: 0,
      inLookbackCount: 0,
      appendCountPlanned: 0,
      rowsMatrix: [],
      sampleRawItemTop1: null,
      top5MappedRows: { columns: [], rows: [] },
      errorMessage: `MAPPING_ERROR: ${err.message}`,
      durationMs: Date.now() - started
    }
  }];
}

const current = $json || {};
let planned;
try {
  planned = $('Map_To_RawEvents_Schema').item.json || {};
} catch {
  planned = current;
}

const appendError = current.error?.message ? String(current.error.message) : null;
const isDryRun = planned.dryRun === true;
const isSkip = planned.skipWorkflow === true;
const nowIso = new Date().toISOString();
const startTs = new Date(planned.jobStartedAtISO || planned.startedAtISO || nowIso).getTime();
const errObj = planned.error || null;
const errorMessage = planned.fatalErrorMessage || planned.errorMessage || appendError || errObj?.message || null;

return [{
  json: {
    dryRun: isDryRun,
    bucket: planned.bucket || null,
    keyword: planned.keyword || null,
    query: planned.query || null,
    proxyCountryCode: planned.proxyCountryCode || null,
    actorUsed: planned.actorUsed || planned.actorNormalized || null,
    requestedDays: planned.requestedDays || planned.days || null,
    jobsCount: planned.jobsCount || null,
    perJobCap: planned.perJobCap || null,
    resultsLimit: planned.resultsLimit || null,
    apifyRunUrl: planned.apifyRunUrl || null,
    apifyDatasetItemsUrlTemplate: planned.apifyDatasetItemsUrlTemplate || null,
    apifyDatasetItemsUrl: planned.apifyDatasetItemsUrl || null,
    sheetsRangesWouldWrite: planned.sheetsRangesWouldWrite || null,
    fetchedCount: isSkip || isDryRun ? Number(planned.fetchedCount || 0) : Number(planned.fetchedCount || 0),
    appendedCount: isSkip || isDryRun || appendError || errorMessage ? 0 : Number(planned.appendCountPlanned || 0),
    inLookbackCount: Number(planned.inLookbackCount || 0),
    sampleRawItemTop1: planned.sampleRawItemTop1 ?? null,
    top5MappedRows: planned.top5MappedRows ?? { columns: [], rows: [] },
    startedAtISO: planned.jobStartedAtISO || planned.startedAtISO || nowIso,
    finishedAtISO: planned.finishedAtISO || nowIso,
    durationMs: Number.isFinite(Number(planned.durationMs)) ? Number(planned.durationMs) : Math.max(0, Date.now() - startTs),
    stage: planned.stage || null,
    error: errObj,
    errorMessage
  }
}];

const items = $input.all().map((i) => i.json || {});
const req = $('Parse_Request').first().json || {};
const startedAtISO = req.startedAtISO || (items[0]?.startedAtISO) || new Date().toISOString();
const finishedAtISO = new Date().toISOString();
const durationMs = Math.max(0, new Date(finishedAtISO).getTime() - new Date(startedAtISO).getTime());
const jobsTotal = items.length;
const jobsFailed = items.filter((i) => i.errorMessage).length;
const jobsSucceeded = Math.max(0, jobsTotal - jobsFailed);
const dryRun = req.dryRun === true;

return [{
  json: {
    workflow: 'KoreaSignals_Collector_TikTok',
    ok: jobsFailed === 0,
    dryRun,
    startedAt: startedAtISO,
    finishedAt: finishedAtISO,
    durationMs,
    jobsTotal,
    jobsSucceeded,
    jobsFailed,
    totalFetched: items.reduce((s, i) => s + Number(i.fetchedCount || 0), 0),
    totalAppended: items.reduce((s, i) => s + Number(i.appendedCount || 0), 0),
    totalInLookback: items.reduce((s, i) => s + Number(i.inLookbackCount || 0), 0),
    sheetsRanges: {
      ensureHeader: `${$env.GSHEET_RAW_TAB || 'raw_events'}!A1:U1`,
      appendRows: `${$env.GSHEET_RAW_TAB || 'raw_events'}!A:U`
    },
    perJobSummary: items
  }
}];
